// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public {
        c = new MyContract();
    }

    function testFuzz_property(address caller, uint256 amount, address receiver) public {
        bound(amount, 1, 100 ether);
        vm.assume(caller != receiver);
        vm.assume(receiver != address(0));
        vm.assume(caller != address(this));
        vm.deal(address(c), amount);

        vm.deal(caller, amount);

        vm.prank(caller);
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(caller == address(this) || !ok);
    }
}
